mapper.select:
select id,logisticsType,carrierCode,carrierCn,carrierEn from ( select id, logistics_type as logisticsType, carrier_code as carrierCode, carrier_cn as carrierCn, carrier_en as carrierEn from logistics_carrier where is_deleted = false
logistics_type = #{params.logisticsType}
and (carrier_code ilike concat('%', #{params.searchKeyword}::text ,'%') or carrier_cn ilike concat('%', #{params.searchKeyword}::text ,'%') or carrier_en ilike concat('%', #{params.searchKeyword}::text ,'%')) order by case when carrier_cn ILIKE concat(#{params.searchKeyword}::text,'%') THEN 1 when carrier_cn ILIKE concat('%',#{params.searchKeyword}::text) THEN 2 when carrier_cn ILIKE concat('%',#{params.searchKeyword}::text,'%') THEN 3 end , carrier_cn
) ca
